css:
.sl-hero-tech {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 85vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-tech .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-tech .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-tech .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-tech .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-tech .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-tech .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-tech .sl-btn-primary:hover,
.sl-hero-tech .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-tech .sl-btn-outline-primary {
  background-color: transparent;
  border: 1px solid var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
.sl-hero-tech .sl-btn-outline-primary:hover,
.sl-hero-tech .sl-btn-outline-primary:focus-visible {
  background-color: var(--smartlearn-btn-bg);
  border-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-tech .font-mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}
.sl-hero-tech .sl-tracking-wide {
  letter-spacing: 0.1em;
}
.sl-hero-tech .sl-tech-lead {
  max-width: 700px;
}
.sl-hero-tech .sl-tech-actions {
  max-width: 460px;
}
.sl-hero-tech .mesh-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--smartlearn-primary) 12%, transparent) 0%, transparent 70%);
}
.sl-hero-tech .pulse-dot {
  width: 8px;
  height: 8px;
  background: var(--smartlearn-primary);
  border-radius: 50%;
}
.sl-hero-tech .sl-tech-title {
  letter-spacing: -0.03em;
}
.sl-hero-tech .tech-btn {
  transition: transform 0.25s ease, box-shadow 0.25s ease, background-color 0.25s ease;
}
.sl-hero-tech .tech-btn:focus-visible {
  outline: 3px solid var(--smartlearn-primary);
  outline-offset: 2px;
}
[dir="rtl"] .sl-hero-tech .sl-rtl-flip {
  transform: scaleX(-1);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-tech .pulse-dot {
    animation: sl-hero-tech-pulse 1.6s infinite;
  }
  .sl-hero-tech .tech-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.2);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-tech .pulse-dot,
  .sl-hero-tech .tech-btn {
    animation: none;
    transition: none;
  }
}
@keyframes sl-hero-tech-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.85); }
}
